    INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, attribution_type, created_by, updated_by, creator_principal_id)
    INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
        (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $body$Masalah: Lidah Kaku saat Harus Ngobrol dalam Bahasa Inggris$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $body$Banyak orang sebenarnya paham grammar dasar bahasa Inggris, tetapi langsung kaku begitu harus berbicara dengan orang asing. Penyebabnya bukan kemampuan bahasa, melainkan tidak tahu harus berkata apa. Small talk — percakapan ringan pembuka — adalah keterampilan terpisah yang bisa dilatih. Tanpa kemampuan ini, peluang kerja, networking, dan pertemanan internasional bisa terlewatkan begitu saja.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $body$Penjelasan: Apa Itu Small Talk dan Kenapa Penting$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $body$Small talk adalah obrolan ringan yang tujuannya bukan bertukar informasi penting, melainkan membangun kehangatan dan kepercayaan. Budaya berbahasa Inggris — terutama di Inggris, Amerika, dan Australia — sangat menghargai small talk sebagai jembatan sebelum masuk ke topik serius. Orang yang mahir small talk dianggap ramah dan mudah diajak kerja sama. Kabar baiknya: small talk memakai pola kalimat yang sangat terbatas dan bisa dihafalkan.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $body$Persiapan: Topik Aman dan Topik yang Dihindari$body$)),
        (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$li$Topik AMAN: cuaca ("Lovely weather today, isn''t it?"), pekerjaan ("What do you do?"), hobi ("What do you do in your free time?"), makanan lokal ("Have you tried the local food?"), perjalanan ("How was your trip?"), pujian yang sopan ("I like your bag, where did you get it?").$li$, $li$Topik yang DIHINDARI: politik, agama, gaji ("How much do you earn?" sangat tidak sopan), usia wanita, berat badan, dan isu sensitif lainnya.$li$, $li$Siapkan jawaban untuk pertanyaan balik — lawan bicara hampir pasti menanyakan hal yang sama kepadamu.$li$]))),
        (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $body$Langkah-Langkah Praktis: Dari Pembuka hingga Percakapan Mengalir$body$)),
        (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$li$Langkah 1 — Sapaan + komentar situasi: "Hi! Great event, isn''t it?" atau "Hello! Have you been waiting long?". Tersenyum dan jaga kontak mata yang wajar.$li$, $li$Langkah 2 — Perkenalkan diri singkat: "I''m Budi, I work in marketing. How about you?" Pertanyaan balik adalah kunci agar percakapan tidak berhenti.$li$, $li$Langkah 3 — Ikuti dengan pertanyaan terbuka: gunakan What, Where, How daripada pertanyaan yes/no. Contoh: "What brought you here?" jauh lebih baik daripada "Did you come alone?".$li$, $li$Langkah 4 — Teknik FORD untuk topik lanjutan: Family (keluarga secara umum), Occupation (pekerjaan), Recreation (hobi/liburan), Dreams (rencana masa depan). Contoh: "Are you planning any holiday this year?"$li$, $li$Langkah 5 — Dengarkan dan tanggapi: gunakan respon pendek seperti "Really?", "That sounds great!", "No way!" lalu lempar pertanyaan lanjutan dari jawabannya.$li$, $li$Langkah 6 — Kalimat penyelamat saat buntu: "By the way, how do you know the host?", "This coffee is good, have you tried it?", atau jujur saja: "Sorry, my English is still basic — but I''d love to practice with you."$li$]))),
        (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $body$Risiko: Kesalahan Umum yang Bikin Canggung$body$)),
        (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$li$Monolog: bicara terlalu lama tentang diri sendiri tanpa memberi kesempatan lawan bicara. Aturannya 50:50.$li$, $li$Pertanyaan interogasi: bertanya bertubi-tubi tanpa menanggapi jawaban terasa seperti wawancara polisi. Selingi dengan komentar.$li$, $li$Topik sensitif: menyebut gaji, politik, atau agama bisa merusak kesan dalam hitungan detik.$li$, $li$Terlalu formal atau terlalu santai: sesuaikan dengan situasi. Di acara resmi hindari slang berat; dengan teman sebaya boleh santai.$li$]))),
        (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $body$Pemeriksaan Hasil dan Tindak Lanjut$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $body$Small talk-mu berhasil bila percakapan bertahan lebih dari 5 menit tanpa jeda canggung yang panjang, lawan bicara tertawa atau mengangguk antusias, ia bertanya balik tentang dirimu, dan — yang paling penting — ia meminta kontakmu ("Can I add you on WhatsApp/LinkedIn?") atau mengajak bertemu lagi. Jika percakapan mati setelah 1 menit, evaluasi: apakah pertanyaanmu terlalu tertutup? Apakah kamu lupa menanggapi jawabannya? Untuk tindak lanjut: tutup percakapan dengan kalimat hangat seperti "It was really nice talking to you! I hope we meet again." atau "I''d better let you mingle — enjoy the event!", tukar kontak bila relevan, dan latih rutin seminggu sekali — hafalkan 5 kalimat pembuka dan 5 pertanyaan FORD, lalu praktikkan dengan teman, komunitas bahasa, atau aplikasi language exchange. Konsistensi mengalahkan bakat: 15 menit latihan seminggu lebih efektif daripada kursus mahal yang tidak dipraktikkan.$body$));
    INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, attribution_type, created_by, updated_by, creator_principal_id)
    INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
        (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $body$Masalah: Gatal yang Mengganggu Aktivitas$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $body$Kulit gatal — dari yang ringan sesekali hingga yang membuat tidak bisa tidur — adalah keluhan yang sangat umum. Menggaruk memang memberi kelegaan sesaat, tetapi justru bisa melukai kulit, menimbulkan luka, infeksi, dan lingkaran gatal-garuk yang makin parah. Memahami penyebabnya adalah langkah pertama agar penanganan tepat sasaran. Catatan: artikel ini adalah informasi umum, bukan pengganti nasihat medis. Jika ragu, konsultasikan ke dokter atau fasilitas kesehatan.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $body$Penjelasan: Mengapa Kulit Bisa Gatal$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $body$Gatal (pruritus) adalah sinyal saraf kulit terhadap rangsangan: kekeringan, iritasi, alergi, gigitan serangga, hingga penyakit kulit seperti eksim atau jamur. Kulit kering adalah penyebab paling umum, terutama di ruangan ber-AC, setelah mandi air panas, atau pada lansia yang produksi minyak kulitnya menurun. Gatal juga bisa menjadi gejala penyakit dalam (misalnya gangguan hati atau ginjal), tetapi ini biasanya disertai gejala lain dan berlangsung lama.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $body$Persiapan: Yang Perlu Disiapkan di Rumah$body$)),
        (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$li$Pelembap (moisturizer) tanpa pewangi — pilih yang berlabel "for sensitive skin" atau "fragrance-free".$li$, $li$Sabun mandi yang lembut (pH seimbang), hindari sabun antiseptik keras untuk pemakaian harian.$li$, $li$Air hangat (bukan panas) untuk mandi; siapkan handuk bersih yang lembut.$li$, $li$Catat pola gatal: kapan muncul, bagian tubuh mana, setelah makan apa, atau setelah memakai produk apa — catatan ini sangat membantu dokter menegakkan diagnosis.$li$]))),
        (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $body$Langkah-Langkah Perawatan yang Aman$body$)),
        (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$li$Langkah 1 — Hentikan siklus garuk: potong kuku pendek, dan saat gatal tekan-tekan kulit dengan telapak tangan dingin atau kompres kain basah dingin selama 10-15 menit.$li$, $li$Langkah 2 — Lembapkan kulit: oleskan pelembap 2-3 kali sehari, terutama dalam 3 menit setelah mandi saat kulit masih sedikit lembap.$li$, $li$Langkah 3 — Mandi dengan benar: batasi 5-10 menit dengan air hangat (bukan panas), pakai sabun hanya di area yang perlu (ketiak, selangkangan, kaki), lalu keringkan dengan menepuk-nepuk handuk, bukan menggosok.$li$, $li$Langkah 4 — Evaluasi produk: hentikan sementara sabun, deterjen, parfum, atau losion baru yang mulai dipakai berdekatan dengan munculnya gatal.$li$, $li$Langkah 5 — Perhatikan makanan dan obat: catat jika gatal muncul setelah makanan tertentu (seafood, kacang) atau obat baru — sampaikan ke dokter, jangan menghentikan obat resep sendiri.$li$, $li$Langkah 6 — Jaga lingkungan: ruangan ber-AC membuat kulit kering — gunakan pelembap udara bila perlu; pilih pakaian katun longgar; cuci sprei dan sarung bantal rutin untuk mengurangi tungau debu.$li$]))),
        (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $body$Risiko dan Tanda Bahaya: Kapan Harus ke Dokter$body$)),
        (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$li$Menggaruk kuat sampai luka membuka pintu infeksi bakteri dan bisa meninggalkan bekas kehitaman.$li$, $li$Mandi air panas terlalu lama meluruhkan minyak alami kulit dan memperparah kekeringan.$li$, $li$Sembarang memakai salep steroid kuat tanpa anjuran dokter bisa menipiskan kulit bila dipakai lama di area sensitif.$li$, $li$SEGERA ke dokter bila: gatal disertai ruam menyebar cepat, bengkak pada wajah/bibir, atau sesak napas (kemungkinan reaksi alergi berat — ini darurat).$li$, $li$Ke dokter bila: kulit bernanah, berkerak kuning, atau demam (tanda infeksi); gatal seluruh tubuh tidak membaik setelah 2 minggu; atau disertai kulit/mata menguning, urine gelap, atau penurunan berat badan tanpa sebab.$li$]))),
        (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $body$Pemeriksaan Hasil dan Tindak Lanjut$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $body$Perawatan mandiri berhasil bila gatal berkurang dalam 3-7 hari, kulit tidak lagi kering bersisik, dan tidak ada luka garukan baru. Lanjutkan pelembap sebagai kebiasaan harian — kulit yang terjaga kelembapannya jauh lebih jarang gatal. Jika gatal kambuh berulang di pola yang sama, bawa catatan pola gatalmu saat konsultasi ke dokter atau puskesmas; diagnosis yang tepat (eksim, alergi, jamur, atau lainnya) menentukan pengobatan yang tepat. Jangan menunda mencari pertolongan medis bila muncul tanda bahaya di atas.$body$));
    INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, attribution_type, created_by, updated_by, creator_principal_id)
    INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
        (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $body$Bumi: Planet Biru yang Didominasi Air$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $body$Sekitar 71 persen permukaan Bumi tertutup air, dan sebagian besarnya adalah samudra — hamparan air asin yang luas dan dalam yang mengelilingi benua-benua. Para ilmuwan membagi samudra dunia menjadi lima: Pasifik, Atlantik, Hindia, Arktik (Utara), dan Antarktik (Selatan). Meski terpisah oleh nama, kelimanya sejatinya satu kesatuan raksasa yang saling terhubung dan mengatur iklim planet ini.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $body$Samudra Pasifik: Sang Raksasa$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $body$Samudra Pasifik adalah yang terluas sekaligus terdalam: luasnya sekitar 165 juta kilometer persegi — lebih luas dari seluruh daratan Bumi digabungkan — dengan titik terdalam Palung Mariana yang mencapai sekitar 11.000 meter. Namanya berarti "tenang" (diberi oleh Magellan), ironisnya wilayah ini justru dikelilingi "Cincin Api" tempat sebagian besar gempa dan gunung berapi dunia terjadi.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $body$Samudra Atlantik, Hindia, dan Dua Kutub$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $body$Samudra Atlantik (sekitar 106 juta km persegi) adalah jalur pelayaran tersibuk dunia dan terus melebar beberapa sentimeter per tahun karena pemekaran dasar laut. Samudra Hindia (sekitar 70 juta km persegi) memandikan pesisir Indonesia dan menjadi jalur perdagangan rempah bersejarah. Samudra Antarktik mengelilingi benua Antarktika dengan arus terkuat di dunia, sedangkan Samudra Arktik adalah yang terkecil dan dangkal, sebagian tertutup es sepanjang tahun.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $body$Mengapa Samudra Penting bagi Kehidupan$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $body$Samudra menghasilkan sebagian besar oksigen yang kita hirup melalui fitoplankton, menyerap panas dan karbon dioksida sehingga menstabilkan iklim, serta menjadi sumber protein bagi miliaran manusia. Arus laut raksasa mendistribusikan panas dari khatulistiwa ke kutub — tanpa sistem ini, iklim benua-benua akan jauh lebih ekstrem.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $body$Ancaman: Samudra yang Terluka$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $body$Samudra kini menghadapi tekanan berat: sampah plastik (termasuk "pulau sampah" raksasa di Pasifik), penangkapan ikan berlebihan, pemutihan terumbu karang akibat air yang menghangat, dan pengasaman laut dari kelebihan CO2. Indonesia sebagai negara kepulauan berada di garis depan — kesehatan laut Nusantara menentukan ketahanan pangan dan ekonomi jutaan nelayan. Mengurangi plastik sekali pakai dan mendukung perikanan berkelanjutan adalah langkah nyata yang bisa dimulai siapa pun.$body$));
    INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, attribution_type, created_by, updated_by, creator_principal_id)
    INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
        (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $body$Apa Itu Komputasi Awan (Cloud Computing)?$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $body$Komputasi awan adalah penyediaan layanan komputasi — server, penyimpanan, database, jaringan, hingga kecerdasan buatan — melalui internet, sehingga pengguna tidak perlu memiliki dan merawat perangkat keras sendiri. Setiap kali kamu menyimpan foto di Google Photos, menonton Netflix, atau memakai email, kamu sedang memakai layanan cloud. Modelnya seperti listrik: kamu memakai sesuai kebutuhan dan membayar sesuai pemakaian, tanpa membangun "pembangkit" sendiri.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $body$Cara Kerja: Dari Data Center hingga Layar HP-mu$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $body$Penyedia cloud mengoperasikan pusat data raksasa berisi ribuan server di berbagai negara. Dengan teknologi virtualisasi, satu server fisik dibagi menjadi banyak "komputer virtual" yang disewakan ke pengguna. Saat kamu mengunggah file, data itu dikirim via internet, disimpan redundan di beberapa lokasi agar aman, dan bisa diakses kapan pun dari perangkat apa pun. Skalabilitas adalah keunggulannya: kapasitas bisa membesar atau mengecil mengikuti kebutuhan dalam hitungan menit.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $body$Tiga Model Layanan Utama$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $body$IaaS (Infrastructure as a Service) menyewakan fondasi mentah — mesin virtual dan penyimpanan — contohnya penyewa server untuk aplikasi. PaaS (Platform as a Service) menyediakan platform siap pakai untuk developer membangun aplikasi tanpa mengurus server. SaaS (Software as a Service) adalah aplikasi jadi yang langsung dipakai, seperti layanan email, dokumen online, dan aplikasi kasir. Ada juga pembagian berdasarkan kepemilikan: public cloud (dipakai bersama publik), private cloud (khusus satu organisasi), dan hybrid (gabungan keduanya).$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $body$Manfaat bagi Bisnis dan Individu$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $body$Bagi startup dan UMKM, cloud menghilangkan kebutuhan modal besar untuk server — bisnis bisa berjalan dengan biaya langganan yang kecil. Bagi individu, file aman dari kerusakan HP karena tersimpan online dan bisa diakses di mana saja. Bagi developer, deploying aplikasi yang dulu butuh berminggu-minggu kini bisa dalam hitungan jam. Fleksibilitas kerja jarak jauh yang meluas dalam beberapa tahun terakhir pun ditopang infrastruktur cloud.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $body$Risiko dan Tantangan yang Perlu Diwaspadai$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $body$Ketergantungan pada koneksi internet adalah kelemahan utama — tanpa internet, layanan tak bisa diakses. Isu keamanan dan privasi data juga nyata: data penting "dititipkan" ke pihak ketiga, sehingga perlu enkripsi, autentikasi berlapis, dan memilih penyedia tepercaya. Ada pula risiko vendor lock-in (sulit pindah penyedia) dan biaya yang membengkak bila pemakaian tidak dimonitor. Aturan kedaulatan data di beberapa negara juga membatasi di mana data boleh disimpan.$body$));
    INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, attribution_type, created_by, updated_by, creator_principal_id)
    INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
        (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $body$Tujuan Pembelajaran$body$)),
        (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$li$Menjelaskan tujuan dan manfaat klasifikasi makhluk hidup.$li$, $li$Mengurutkan tingkatan takson dari yang tertinggi hingga terendah.$li$, $li$Mengidentifikasi ciri lima kingdom dalam sistem Whittaker.$li$, $li$Menuliskan nama ilmiah makhluk hidup sesuai tata nama binomial.$li$]))),
        (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $body$Mengapa Makhluk Hidup Perlu Diklasifikasikan?$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $body$Para ilmuwan memperkirakan ada jutaan jenis makhluk hidup di Bumi. Tanpa pengelompokan, mustahil mempelajarinya satu per satu. Klasifikasi adalah pengelompokan makhluk hidup berdasarkan persamaan dan perbedaan ciri. Tujuannya: mempermudah pengenalan, menunjukkan hubungan kekerabatan, dan memberi nama yang seragam secara internasional. Pelopor klasifikasi modern adalah Carolus Linnaeus, ilmuwan Swedia abad ke-18 yang sistemnya masih dipakai hingga kini.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $body$Tingkatan Takson: Dari Kingdom hingga Spesies$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $body$Takson adalah kelompok dalam klasifikasi. Urutannya dari yang terbesar: Kingdom (kerajaan) → Filum (untuk hewan) atau Divisi (untuk tumbuhan) → Kelas → Ordo (bangsa) → Famili (suku) → Genus (marga) → Spesies (jenis). Semakin ke bawah, persamaan cirinya semakin banyak. Cara mudah menghafal: "Ki Fikri Kelas Orangnya Family-nya Genius Sekali". Contoh penerapan — klasifikasi kucing peliharaan: Kingdom Animalia (hewan), Filum Chordata (bertulang belakang), Kelas Mammalia (menyusui), Ordo Carnivora (pemakan daging), Famili Felidae (keluarga kucing), Genus Felis, Spesies Felis catus. Perhatikan: kucing dan harimau satu famili (Felidae) tetapi berbeda genus dan spesies — artinya mereka berkerabat dekat tetapi bukan jenis yang sama.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $body$Sistem Lima Kingdom Whittaker$body$)),
        (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$li$Monera: bersel satu tanpa membran inti (prokariotik), contoh bakteri dan ganggang biru.$li$, $li$Protista: bersel satu atau banyak tetapi sederhana, berinti sejati (eukariotik), contoh amoeba, paramecium, dan ganggang.$li$, $li$Fungi (jamur): tidak berklorofil, memperoleh makanan dengan menguraikan bahan organik, contoh jamur merang dan ragi.$li$, $li$Plantae (tumbuhan): berklorofil dan berfotosintesis, contoh padi, mangga, dan lumut.$li$, $li$Animalia (hewan): tidak berklorofil, memperoleh makanan dengan memakan makhluk lain, contoh ikan, burung, dan manusia.$li$]))),
        (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $body$Tata Nama Binomial: Aturan Penulisan Nama Ilmiah$body$)),
        (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$li$Nama ilmiah terdiri dari dua kata: nama genus (huruf pertama kapital) + nama spesies (huruf kecil semua). Contoh: Oryza sativa (padi), Felis catus (kucing).$li$, $li$Ditulis miring (italic) pada teks cetak, atau digarisbawahi jika ditulis tangan.$li$, $li$Satu nama ilmiah hanya untuk satu jenis makhluk hidup di seluruh dunia — tidak ada duplikat, berbeda dengan nama daerah yang bisa sama untuk tumbuhan berbeda.$li$]))),
        (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $body$Latihan Soal dan Kunci Jawaban$body$)),
        (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$li$Soal 1: Sebutkan urutan tingkatan takson dari yang tertinggi hingga terendah! → Kunci: Kingdom → Filum/Divisi → Kelas → Ordo → Famili → Genus → Spesies.$li$, $li$Soal 2: Jelaskan dua tujuan klasifikasi makhluk hidup! → Kunci: mempermudah pengenalan dan mempelajari makhluk hidup; menunjukkan hubungan kekerabatan; memberi nama seragam internasional (pilih dua).$li$, $li$Soal 3: Tuliskan nama ilmiah mangga (Mangifera indica) dengan aturan yang benar, lalu sebutkan genusnya! → Kunci: ditulis miring: Mangifera indica; genusnya Mangifera.$li$, $li$Soal 4: Mengapa jamur tidak dimasukkan ke dalam kingdom Plantae? → Kunci: karena jamur tidak berklorofil dan tidak berfotosintesis; ia memperoleh makanan dengan menguraikan bahan organik.$li$, $li$Soal 5: Sebutkan tiga contoh makhluk hidup kingdom Monera beserta perannya! → Kunci: bakteri pengurai, bakteri nitrogen (Rhizobium) yang menyuburkan tanah, dan ganggang biru (Cyanobacteria) yang berfotosintesis.$li$])));
    INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, attribution_type, created_by, updated_by, creator_principal_id)
    INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
        (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $body$Tujuan Pembelajaran$body$)),
        (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$li$Menjelaskan pengertian dan tujuan pidato.$li$, $li$Menyusun teks pidato dengan struktur pembuka, isi, dan penutup.$li$, $li$Mempraktikkan teknik vokal dan bahasa tubuh saat berpidato.$li$, $li$Tampil berpidato di depan kelas dengan percaya diri.$li$]))),
        (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $body$Apa Itu Pidato?$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $body$Pidato adalah kegiatan menyampaikan gagasan, pendapat, atau informasi kepada banyak orang secara lisan. Kita sering mendengarnya saat upacara bendera, perayaan hari besar, atau sambutan acara sekolah. Tujuan pidato bermacam-macam: memberi informasi, mengajak (persuasi), atau menghibur. Orang yang berpidato disebut orator. Berpidato melatih keberanian, kemampuan berpikir runtut, dan keterampilan berbicara — bekal penting untuk masa depan.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $body$Struktur Pidato: Pembuka, Isi, Penutup$body$)),
        (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$li$Pembuka: salam pembuka, sapaan kepada hadirin (yang terhormat...), dan perkenalan diri singkat. Contoh: "Assalamualaikum warahmatullahi wabarakatuh. Yang terhormat Bapak Kepala Sekolah..."$li$, $li$Isi: gagasan utama yang ingin disampaikan, disusun runtut dengan contoh atau alasan yang mendukung.$li$, $li$Penutup: rangkuman singkat, ajakan atau harapan, ucapan terima kasih, dan salam penutup.$li$]))),
        (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $body$Teknik Vokal dan Bahasa Tubuh$body$)),
        (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$li$Volume: cukup keras agar terdengar barisan paling belakang, tetapi tidak berteriak.$li$, $li$Kecepatan: jangan terlalu cepat (sulit dipahami) atau terlalu lambat (membosankan); beri jeda di bagian penting.$li$, $li$Intonasi: naik-turunkan nada suara; tekankan kata-kata kunci agar pendengar tidak mengantuk.$li$, $li$Artikulasi: ucapkan setiap kata dengan jelas — latihan dengan membaca teks keras-keras di depan cermin.$li$, $li$Berdiri tegak dan tenang; hindari menggoyangkan badan atau memainkan benda di tangan.$li$, $li$Tatap hadirin bergantian, jangan hanya menunduk membaca teks; gunakan gerakan tangan secukupnya.$li$, $li$Tersenyum ramah di awal dan akhir; pakaian rapi menambah kepercayaan diri.$li$]))),
        (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $body$Contoh Kerangka Pidato Singkat$body$)),
        (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $body$Tema: Menjaga Kebersihan Sekolah. Pembuka: salam dan sapaan. Isi: (1) kebersihan membuat belajar nyaman, (2) contoh sederhana: buang sampah pada tempatnya dan piket kelas, (3) ajakan: "Mari kita mulai dari diri sendiri, dari hal kecil, dari sekarang." Penutup: harapan sekolah bersih dan sehat, terima kasih, salam penutup. Dari kerangka ini, kembangkan menjadi teks pidato 1-2 halaman dengan bahasamu sendiri.$body$)),
        (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $body$Latihan Soal dan Kunci Jawaban$body$)),
        (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$li$Soal 1: Apa yang dimaksud dengan pidato dan siapa yang menyampaikannya? → Kunci: pidato adalah penyampaian gagasan/pendapat/informasi secara lisan kepada banyak orang; yang menyampaikan disebut orator.$li$, $li$Soal 2: Sebutkan tiga bagian struktur pidato beserta isinya masing-masing! → Kunci: pembuka (salam, sapaan, perkenalan), isi (gagasan utama yang runtut), penutup (rangkuman, ajakan/harapan, terima kasih, salam).$li$, $li$Soal 3: Mengapa intonasi penting saat berpidato? Jelaskan! → Kunci: intonasi membuat pidato hidup dan tidak monoton; penekanan nada membantu pendengar menangkap bagian penting.$li$, $li$Soal 4: Sebutkan tiga hal yang harus dihindari dari bahasa tubuh saat berpidato! → Kunci: menggoyangkan badan, menunduk terus membaca teks, memainkan benda di tangan, tidak menatap hadirin (pilih tiga).$li$, $li$Soal 5: Buatlah kerangka pidato bertema "Rajin Membaca" dengan struktur pembuka-isi-penutup! → Kunci: dinilai dari kelengkapan struktur — ada salam/sapaan, gagasan tentang manfaat membaca yang runtut, dan ajakan + salam penutup.$li$])));
